import type { ImageFormat } from "@/lib/domain";

const DIMENSIONS: Record<ImageFormat, [number, number]> = {
  "1:1": [1080, 1080],
  "4:5": [1080, 1350],
  "16:9": [1200, 675],
};

/**
 * Fake image (abstract SVG, no text) the fake API uses in place of images
 * generated by the agent. The same seed makes the same image.
 */
export function fakeImage(seed: string, format: ImageFormat = "1:1"): string {
  let hash = 2166136261;
  for (const c of seed)
    hash = Math.imul(hash ^ c.charCodeAt(0), 16777619) >>> 0;
  const hue = hash % 360;
  const [w, h] = DIMENSIONS[format];
  const circle = (i: number) => {
    const x = ((hash >> (i * 3)) % 100) / 100;
    const y = ((hash >> (i * 5)) % 100) / 100;
    const r = 0.15 + ((hash >> i) % 30) / 100;
    return `<circle cx="${Math.round(x * w)}" cy="${Math.round(y * h)}" r="${Math.round(r * Math.min(w, h))}" fill="hsl(${(hue + i * 40) % 360} 80% 70%)" fill-opacity="0.55"/>`;
  };
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="hsl(${hue} 70% 45%)"/><stop offset="1" stop-color="hsl(${(hue + 60) % 360} 70% 25%)"/></linearGradient></defs><rect width="${w}" height="${h}" fill="url(#g)"/>${[1, 2, 3].map(circle).join("")}</svg>`;
  return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`;
}
